<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionTemplateVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionSubjectVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionContentHtmlVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionContentTextVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionVersionVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Retrieve\TemplateVersionRetrieveResult;
use PHPUnit\Framework\TestCase;

final class TemplateVersionRetrieveResultUnitTest extends TestCase
{
  public function test(): void
  {
    $value = new TemplateVersionRetrieveResult();
    $templateOneValue = new TemplateRef('one');
    $templateOtherValue = new TemplateRef('other');
    $copy = $value->template($templateOneValue);
    $this->assertSame($value, $copy);
    $this->assertEquals(new TemplateRef('one'), $value->getTemplate());
    $this->assertNotEquals(new TemplateRef('other'), $value->getTemplate());
    $this->assertEquals(new TemplateRef('one'), $value->getTemplateOrDefault(TemplateVersionTemplateVO::from($templateOtherValue))->value());
    $this->assertNotEquals(new TemplateRef('other'), $value->getTemplateOrDefault(TemplateVersionTemplateVO::from($templateOtherValue))->value());
    $value->unsetTemplate();
    $this->assertEquals(new TemplateRef('other'), $value->getTemplateOrDefault(TemplateVersionTemplateVO::from($templateOtherValue))->value());
    $this->assertNotEquals(new TemplateRef('one'), $value->getTemplateOrDefault(TemplateVersionTemplateVO::from($templateOtherValue))->value());
    $subjectOneValue = 'one';
    $subjectOtherValue = 'other';
    $copy = $value->subject($subjectOneValue);
    $this->assertSame($value, $copy);
    $this->assertEquals('one', $value->getSubject());
    $this->assertNotEquals('other', $value->getSubject());
    $this->assertEquals('one', $value->getSubjectOrDefault(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
    $this->assertNotEquals('other', $value->getSubjectOrDefault(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
    $value->unsetSubject();
    $this->assertEquals('other', $value->getSubjectOrDefault(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
    $this->assertNotEquals('one', $value->getSubjectOrDefault(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
    $contentHtmlOneValue = 'one';
    $contentHtmlOtherValue = 'other';
    $copy = $value->contentHtml($contentHtmlOneValue);
    $this->assertSame($value, $copy);
    $this->assertEquals('one', $value->getContentHtml());
    $this->assertNotEquals('other', $value->getContentHtml());
    $this->assertEquals('one', $value->getContentHtmlOrDefault(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
    $this->assertNotEquals('other', $value->getContentHtmlOrDefault(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
    $value->unsetContentHtml();
    $this->assertEquals('other', $value->getContentHtmlOrDefault(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
    $this->assertNotEquals('one', $value->getContentHtmlOrDefault(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
    $contentTextOneValue = 'one';
    $contentTextOtherValue = 'other';
    $copy = $value->contentText($contentTextOneValue);
    $this->assertSame($value, $copy);
    $this->assertEquals('one', $value->getContentText());
    $this->assertNotEquals('other', $value->getContentText());
    $this->assertEquals('one', $value->getContentTextOrDefault(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
    $this->assertNotEquals('other', $value->getContentTextOrDefault(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
    $value->unsetContentText();
    $this->assertEquals('other', $value->getContentTextOrDefault(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
    $this->assertNotEquals('one', $value->getContentTextOrDefault(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
    $versionOneValue = 1;
    $versionOtherValue = 2;
    $copy = $value->version($versionOneValue);
    $this->assertSame($value, $copy);
    $this->assertEquals(1, $value->getVersion());
    $this->assertNotEquals(2, $value->getVersion());
    $this->assertEquals(1, $value->getVersionOrDefault(TemplateVersionVersionVO::from($versionOtherValue))->value());
    $this->assertNotEquals(2, $value->getVersionOrDefault(TemplateVersionVersionVO::from($versionOtherValue))->value());
    $value->unsetVersion();
    $this->assertEquals(2, $value->getVersionOrDefault(TemplateVersionVersionVO::from($versionOtherValue))->value());
    $this->assertNotEquals(1, $value->getVersionOrDefault(TemplateVersionVersionVO::from($versionOtherValue))->value());
    $this->assertSame($value, $copy);
  }
}
